const report='D:/Development/GitHub/.codex-worktrees/healthroster-v2-report-build-13102026',root='D:/Development/GitHub/.codex-worktrees/healthroster-install2-14102026',operator='docs/healthroster-build/proposals/daily-health-genuine-staged-operator-20261017',here=path.dirname(fileURLToPath(import.meta.url));
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const git=(repository,...args)=>cp.execFileSync('git',['-c','gc.auto=0','-c','maintenance.auto=false','-c','core.autocrlf=false','-c','core.longpaths=true','-C',repository,...args],{maxBuffer:32e6,windowsHide:true,stdio:['ignore','pipe','ignore'],env:{...process.env,GIT_OPTIONAL_LOCKS:'0',GIT_NO_LAZY_FETCH:'1'}});
