export async function withSharedRehearsalTurn({task,progressPath,work,monitorMs=5000,beforePhase},deps={}){
 const now=deps.now??(()=>Date.now());
 const lastBusy=deps.readLastBusy??(()=>{
  if(!progressPath||!fs.existsSync(progressPath))return null;
  let latest=null;
  for(const line of fs.readFileSync(progressPath,'utf8').split(/\r?\n/)){
   if(!line.startsWith('SEND_7 turn: '))continue;
   const record=JSON.parse(line.slice('SEND_7 turn: '.length));
   if(record.chat==='HealthRoster'&&record.status==='BUSY_NO_TRIAL'){
    const time=Date.parse(record.checkedAt);if(!Number.isFinite(time))throw Error('TURN_BUSY_TIMESTAMP_INVALID');
    latest=Math.max(latest??time,time);
   }
  }
  return latest;
 });
 const busyAt=lastBusy();
 if(busyAt!==null){
  if(!Number.isFinite(busyAt))throw Error('TURN_BUSY_TIMESTAMP_INVALID');
  if(now()<busyAt+300000)return {status:'COOLDOWN_NO_CONNECTION',nextEligibleAt:new Date(busyAt+300000).toISOString()};
 }
 const check=deps.checkProtectedRelease??assertNoProtectedRelease;
 const open=deps.openTurn??(()=>new OwnedTurnConnection(agencyChildEnvironment('healthroster_rehearsal_turn')));
 const writeLog=deps.log??(record=>{fs.appendFileSync(progressPath,'\nSEND_7 turn: '+JSON.stringify(record)+'\n');});
 await check();const connection=open();let taken=false,takenAt=null,releaseConfirmed=false,primaryError,result,monitor,probe,control;
 const controller=new AbortController();
 const log=record=>{try{writeLog(record);}catch{const error=closedTurnError('TURN_JOURNAL_WRITE_FAILED');if(!controller.signal.aborted)controller.abort(error);throw error;}};
 const lose=error=>{if(!controller.signal.aborted){controller.abort(error);try{log({chat:'HealthRoster',task,status:'LOST_INCOMPLETE',at:new Date().toISOString(),code:error.code??'SHARED_TURN_LOST',key:TURN_KEY});}catch{/* Loss stays contained in this controller; cleanup owns its children. */}}};
 const connectionLost=()=>lose(connection.signal.reason??closedTurnError('TURN_CONNECTION_CLOSED'));
 connection.signal?.addEventListener('abort',connectionLost,{once:true});
 try {
  const answer=await connection.query('select pg_try_advisory_lock(20261013, 1);');
  if(answer.length!==1||!['t','f'].includes(answer[0]))throw Error('TURN_LOCK_RESULT_REFUSED');
  if(answer[0]==='f'){log({chat:'HealthRoster',task,status:'BUSY_NO_TRIAL',checkedAt:new Date().toISOString(),nextAttemptAfterMinutes:5});return {status:'BUSY_NO_TRIAL'};}
  taken=true;takenAt=new Date().toISOString();log({chat:'HealthRoster',task,status:'TAKEN',takenAt,key:TURN_KEY});
  const identity=await connection.query("select current_database()='cloudtms_test_clone' and exists(select 1 from private.cloudtms_database_identity where singleton and environment='TEST') and exists(select 1 from private.bpay_next_module_control where id=1 and active_owner='LEGACY' and owner_epoch=1) and not exists(select 1 from private.cloudtms_database_releases where status='APPLYING');");
  if(identity.length!==1||identity[0]!=='t')throw Error('TURN_TEST_IDENTITY_OR_RELEASE_REFUSED');
  const owned=readOwnership(await connection.query(TURN_OWNERSHIP_SQL));
  const trusted=Object.freeze({physicalDatabase:owned.physicalDatabase,databaseOid:owned.databaseOid,backendPid:owned.backendPid,
   turnId:'hr_turn_'+crypto.randomBytes(16).toString('hex'),key:TURN_KEY,takenAt,task});
  const assertHeld=async phase=>{
   if(controller.signal.aborted)throw controller.signal.reason;
   // Interval and phase checks share one small probe; no concurrent psql input.
   if(!probe){probe=(async()=>{try{readOwnership(await connection.query(TURN_OWNERSHIP_SQL),trusted);}catch(error){lose(error);throw error;}finally{probe=null;}})();}
   await probe;if(controller.signal.aborted)throw controller.signal.reason;
   // Optional coordinator gate can re-read Banking's completed install/turn
   // record and exact shared source immediately before protected dispatch.
   if(phase&&beforePhase)await beforePhase(phase,trusted);
   if(controller.signal.aborted)throw controller.signal.reason;
  };
  if(!Number.isFinite(monitorMs)||monitorMs<1)throw Error('TURN_MONITOR_INTERVAL_REFUSED');
  monitor=setInterval(()=>{void assertHeld().catch(()=>{});},monitorMs);
  const context={turnConnection:connection,takenAt,identity:trusted,signal:controller.signal,assertHeld,
   activityExclusionSql:ownTurnActivityExclusionSql(trusted),
   runOwnedChild:options=>runOwnedTurnChild({...options,signal:controller.signal,assertHeld}),
   async managedReleaseEnvironment(){await assertHeld('managed-release-control');control??=await serveTurnControl({identity:trusted,signal:controller.signal,assertHeld});return control.environment;},
   async runManagedRelease({npmCli,connectionsProof,officePath,cwd=process.cwd(),env=process.env,node=process.execPath}){
    if(!path.isAbsolute(npmCli)||!path.isAbsolute(connectionsProof))throw Error('MANAGED_RELEASE_ABSOLUTE_INPUTS_REQUIRED');
    const shared=await context.managedReleaseEnvironment();
    return context.runOwnedChild({file:node,args:[npmCli,'run','release:test','--','--shared-turn',`--connections-proof=${connectionsProof}`,...officePath?[`--office-path=${officePath}`]:[]],
     options:{cwd,env:{...env,...shared},stdio:['ignore','pipe','pipe']},cancelOnLoss:false});
   }};
  // The same retained session spans before/full SQL/rollback/fresh proof AND
  // managed database wait, ordered runtime publication and Office publication.
  await assertHeld('before-work');result=await work(context);await assertHeld('callback-complete');
 } catch(error){primaryError=error;
 } finally {
  clearInterval(monitor);try{await probe;}catch(error){primaryError??=error;}
  try{await control?.close();}catch(error){primaryError??=error;}
  try{if(taken){const unlock=await connection.query('select pg_advisory_unlock(20261013, 1);');releaseConfirmed=unlock.length===1&&unlock[0]==='t';}}catch(error){primaryError??=error;}
  let connectionClosed=false;try{await connection.close();connectionClosed=true;}catch(error){primaryError??=error;}
  connection.signal?.removeEventListener('abort',connectionLost);
  if(taken)try{log({chat:'HealthRoster',task,status:'RELEASED',takenAt,releasedAt:new Date().toISOString(),explicitUnlockConfirmed:releaseConfirmed,connectionClosed,
   proved:!primaryError&&!controller.signal.aborted&&releaseConfirmed&&connectionClosed,key:TURN_KEY});}catch(error){primaryError??=error;}
  // Preserve the original source/child error; cleanup failure never hides it.
  if(taken&&!releaseConfirmed){if(primaryError)primaryError.turnUnlockConfirmed=false;else primaryError=closedTurnError('TURN_UNLOCK_CONFIRMATION_FAILED');}
  if(controller.signal.aborted)primaryError??=controller.signal.reason;
 }
 if(primaryError)throw primaryError;return result;
}

import net from 'node:net';
import crypto from 'node:crypto';
import os from 'node:os';
import path from 'node:path';
import {spawn} from 'node:child_process';

export function closedTurnError(code='SHARED_TURN_LOST') { return Object.assign(Error(code),{code}); }
export function assertTurnIdentity(identity) {
 if(identity?.physicalDatabase!=='cloudtms_test_clone'||!Number.isSafeInteger(identity.databaseOid)||identity.databaseOid<1
  ||!Number.isSafeInteger(identity.backendPid)||identity.backendPid<1||!/^hr_turn_[a-f0-9]{32}$/.test(identity.turnId??'')
  ||JSON.stringify(identity.key)!=='[20261013,1]')throw closedTurnError('SHARED_TURN_IDENTITY_REFUSED');
 return identity;
}

// Exclude ONLY the proved same-database turn PID and the activity query itself.
// An application_name match or caller-supplied extra PID is never an exemption.
export function ownTurnActivityExclusionSql(identity) {
 assertTurnIdentity(identity);
 return `pid <> pg_backend_pid() and not (pid = ${identity.backendPid} and datid = ${identity.databaseOid})`;
}

export function abortableDelay(ms,signal) {
 if(signal?.aborted)return Promise.reject(signal.reason);
 return new Promise((resolve,reject)=>{
  const done=()=>{clearTimeout(timer);signal?.removeEventListener('abort',abort);resolve();};
  const abort=()=>{clearTimeout(timer);signal?.removeEventListener('abort',abort);reject(signal.reason);};
  const timer=setTimeout(done,ms);signal?.addEventListener('abort',abort,{once:true});
 });
}

// No wall-clock limit on full SQL. Cancellation is exclusively a loss signal
// applied to the exact child object created here; no PID search or remote cancel.
export async function runOwnedTurnChild({file,args=[],options={},input,signal,assertHeld,cancelOnLoss=true,spawnChild=spawn,resourceGuard}) {
 await assertHeld('before-owned-child');
 if(signal.aborted)throw signal.reason;
 if(resourceGuard&&(!cancelOnLoss||typeof resourceGuard.start!=='function'||typeof resourceGuard.stop!=='function'))throw closedTurnError('RESOURCE_GUARD_ONLY_FOR_OWN_ROLLBACK_CHILD');
 const child=spawnChild(file,args,{...options,windowsHide:true});
 return await new Promise((resolve,reject)=>{
  let stdout='',stderr='',killTimer,inputError,observerError,resourceError,ownedClosed=false;
  const stopOwnedChild=()=>{if(ownedClosed)return;child.kill('SIGTERM');killTimer=setTimeout(()=>{if(!ownedClosed)child.kill('SIGKILL');},5000);killTimer.unref?.();};
  const observe=(callback,chunk)=>{
   if(observerError||!callback)return;
   try{callback(chunk);}catch{
    observerError=closedTurnError('OWNED_CHILD_OBSERVER_FAILED');
    // A failed rollback observer closes only its own child. A dispatched
    // durable release is allowed to finish, then held for reconciliation.
    if(cancelOnLoss){child.kill('SIGTERM');killTimer=setTimeout(()=>child.kill('SIGKILL'),5000);killTimer.unref?.();}
   }
  };
  const abort=()=>{if(cancelOnLoss){child.kill('SIGTERM');killTimer=setTimeout(()=>child.kill('SIGKILL'),5000);killTimer.unref?.();}};
  child.stdout?.on('data',chunk=>{stdout+=chunk.toString();observe(options.onStdout,chunk);});
  child.stderr?.on('data',chunk=>{stderr+=chunk.toString();observe(options.onStderr,chunk);});
  child.stdin?.on('error',()=>{
   inputError=closedTurnError('OWNED_CHILD_INPUT_FAILED');
   child.kill('SIGTERM');killTimer=setTimeout(()=>child.kill('SIGKILL'),5000);killTimer.unref?.();
  });
  signal.addEventListener('abort',abort,{once:true});
  child.once('error',()=>{signal.removeEventListener('abort',abort);clearTimeout(killTimer);reject(closedTurnError('OWNED_CHILD_START_FAILED'));});
  child.once('close',async(code,childSignal)=>{
   ownedClosed=true;
   signal.removeEventListener('abort',abort);clearTimeout(killTimer);
   if(resourceGuard)try{const result=await resourceGuard.stop();if(result.failed)resourceError??=closedTurnError(result.code);}catch{resourceError??=closedTurnError('REHEARSAL_RESOURCE_OBSERVATION_FAILED');}
   if(signal.aborted){reject(signal.reason);return;}
   if(inputError){reject(inputError);return;}
   if(observerError){reject(observerError);return;}
   if(resourceError){reject(resourceError);return;}
   try {await assertHeld('after-owned-child');resolve({code,signal:childSignal,stdout,stderr});}catch(error){reject(error);}
  });
  if(resourceGuard)try{resourceGuard.start(cause=>{resourceError??=closedTurnError(cause.code??'REHEARSAL_RESOURCE_OBSERVATION_FAILED');stopOwnedChild();});}catch{resourceError=closedTurnError('REHEARSAL_RESOURCE_GUARD_START_FAILED');stopOwnedChild();}
  if(input!==undefined){if(typeof input!=='string'||!child.stdin){child.kill('SIGTERM');reject(closedTurnError('OWNED_CHILD_INPUT_REFUSED'));return;}child.stdin.end(input);}
  if(signal.aborted)abort();
 });
}

// A per-process capability and a local pipe bind the canonical npm coordinator
// to this still-open turn. Neither is a saved proof or database credential.
export async function serveTurnControl({identity,signal,assertHeld}) {
 assertTurnIdentity(identity);
 const capability=crypto.randomBytes(32).toString('hex');
 const pipe=process.platform==='win32'?`\\\\.\\pipe\\healthroster-turn-${process.pid}-${crypto.randomBytes(12).toString('hex')}`
  :path.join(os.tmpdir(),`hr-turn-${process.pid}-${crypto.randomBytes(12).toString('hex')}.sock`);
 const peers=new Set();
 const server=net.createServer(socket=>{
  let authenticated=false,buffer='';
  const send=value=>{if(!socket.destroyed)socket.write(JSON.stringify(value)+'\n');};
  socket.on('data',chunk=>{
   buffer+=chunk.toString();if(buffer.length>16384){socket.destroy();return;}
   let end;while((end=buffer.indexOf('\n'))>=0){const line=buffer.slice(0,end);buffer=buffer.slice(end+1);
    let request;try{request=JSON.parse(line);}catch{socket.destroy();return;}
    if(!authenticated){
     if(request.type!=='hello'||typeof request.capability!=='string'||request.capability!==capability){socket.destroy();return;}
     authenticated=true;peers.add(socket);send({type:'identity',identity});
     if(signal.aborted)send({type:'lost',code:'SHARED_TURN_LOST'});
    } else if(request.type==='check'&&Number.isSafeInteger(request.id)&&typeof request.phase==='string'){
     void assertHeld(request.phase).then(()=>send({type:'checked',id:request.id}),()=>send({type:'lost',code:'SHARED_TURN_LOST'}));
    } else socket.destroy();
   }
  });
  socket.on('error',()=>{});socket.once('close',()=>peers.delete(socket));
 });
 await new Promise((resolve,reject)=>{server.once('error',reject);server.listen(pipe,resolve);});
 const loss=()=>{for(const socket of peers)socket.write(JSON.stringify({type:'lost',code:'SHARED_TURN_LOST'})+'\n');};
 signal.addEventListener('abort',loss,{once:true});
 return {environment:{CLOUDTMS_SHARED_TURN_PIPE:pipe,CLOUDTMS_SHARED_TURN_CAPABILITY:capability},async close(){
  signal.removeEventListener('abort',loss);for(const socket of peers)socket.destroy();await new Promise(resolve=>server.close(resolve));
 }};
}

export async function connectTurnControl(env=process.env,{connect=net.createConnection,probeMs=10000}={}) {
 if(!env.CLOUDTMS_SHARED_TURN_PIPE||!env.CLOUDTMS_SHARED_TURN_CAPABILITY)throw closedTurnError('SHARED_TURN_CONTROL_REQUIRED');
 const controller=new AbortController(),pending=new Map();let identity,buffer='',sequence=0,closing=false;
 const socket=connect(env.CLOUDTMS_SHARED_TURN_PIPE);
 const lose=code=>{if(!closing&&!controller.signal.aborted)controller.abort(closedTurnError(code));for(const item of pending.values()){clearTimeout(item.timer);item.reject(controller.signal.reason??closedTurnError(code));}pending.clear();};
 const ready=new Promise((resolve,reject)=>{
  const timer=setTimeout(()=>{lose('SHARED_TURN_CONTROL_TIMEOUT');reject(controller.signal.reason);socket.destroy();},probeMs);
  socket.once('connect',()=>socket.write(JSON.stringify({type:'hello',capability:env.CLOUDTMS_SHARED_TURN_CAPABILITY})+'\n'));
  socket.on('data',chunk=>{
   buffer+=chunk.toString();if(buffer.length>16384){lose('SHARED_TURN_CONTROL_REFUSED');socket.destroy();return;}
   let end;while((end=buffer.indexOf('\n'))>=0){const line=buffer.slice(0,end);buffer=buffer.slice(end+1);
    let response;try{response=JSON.parse(line);}catch{lose('SHARED_TURN_CONTROL_REFUSED');return;}
    if(response.type==='identity'&&!identity){try{identity=assertTurnIdentity(response.identity);clearTimeout(timer);resolve();}catch(error){clearTimeout(timer);reject(error);lose(error.code);}}
    else if(response.type==='checked'&&pending.has(response.id)){const item=pending.get(response.id);pending.delete(response.id);clearTimeout(item.timer);item.resolve();}
    else if(response.type==='lost'){lose('SHARED_TURN_LOST');clearTimeout(timer);reject(controller.signal.reason);}
    else {lose('SHARED_TURN_CONTROL_REFUSED');clearTimeout(timer);reject(controller.signal.reason);}
   }
  });
  socket.on('error',()=>{clearTimeout(timer);lose('SHARED_TURN_CONTROL_CLOSED');reject(controller.signal.reason);});
  socket.once('close',()=>{clearTimeout(timer);lose('SHARED_TURN_CONTROL_CLOSED');reject(controller.signal.reason);});
 });
 await ready;
 return {identity,signal:controller.signal,async assertHeld(phase){
  if(controller.signal.aborted)throw controller.signal.reason;
  const id=++sequence;
  await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{lose('SHARED_TURN_CONTROL_TIMEOUT');socket.destroy();},probeMs);pending.set(id,{resolve,reject,timer});socket.write(JSON.stringify({type:'check',id,phase})+'\n');});
  if(controller.signal.aborted)throw controller.signal.reason;
 },close(){closing=true;socket.destroy();}};
}

